  tl_hint_align: 'Alinear: haga clic en la referencia y luego en lo que desea alinear. Ctrl+clic acumula varios; Tab alterna la entidad bajo el cursor; Esc retrocede un paso.',
  tl_hint_angdim: 'Cota angular: haga clic en la primera referencia y luego en la segunda. Mueva el cursor para elegir el lado (interno = menor, externo = vuelta >180°) y el radio del arco; haga clic para crear. Tab alterna la referencia.',
  tl_hint_attach_roof: 'Adjuntar parte superior: haga clic en los muros (o selecciónelos antes) y luego Enter. Esc sale.',
  tl_hint_attach_roof_pick: 'Seleccione el tejado: la parte superior de los muros elegidos sigue su cara inferior. Enter vuelve a los muros.',
  tl_hint_detach_roof: 'Separar parte superior: seleccione los muros y pulse Enter, o haga clic en un muro adjunto. Esc sale.',
  tl_hint_ceiling: 'Cielo raso: cree el contorno con el modo Crear/Editar perímetro.',
  tl_hint_detail_line: 'Línea de detalle: haga clic en el inicio y en el final.',
  tl_hint_filled_region: 'Región rellena: haga clic en los vértices y pulse Enter para cerrar.',
  tl_hint_dimension: 'Cota: haga clic en el primer punto medido y luego en el segundo. Mueva el cursor hacia el lado de la línea de cota y haga clic (o escriba el desplazamiento).',
  tl_hint_floor: 'Piso: cree el contorno con el modo Crear/Editar perímetro.',
  tl_hint_grid_line: 'Cuadrícula: haga clic en el inicio y el final del eje, o escriba la longitud y pulse Enter.',
  tl_hint_grid_arc: 'Cuadrícula en arco: haga clic en el inicio, el final y un punto del arco (o escriba la flecha).',
  tl_hint_grid_pick: 'Cuadrícula: haga clic en un muro para crear la cuadrícula sobre su eje.',
  tl_hint_grid_multi: 'Cuadrícula multisegmento: haga clic en los puntos; Enter o doble clic termina, Esc elimina el último punto.',
  tl_hint_join: 'Unión: haga clic en una esquina de dos muros para alternar Tope e Inglete (Tab invierte la dominancia). En T o nudo, haga clic para no unir el extremo. Escalera/rampa: use Editar boceto.',
  tl_hint_level: 'Nivel: haga clic en el inicio de la línea de nivel. El final queda en la misma cota. Esc cancela.',
  tl_hint_offset: 'Desplazar: pase sobre un muro, una arista de piso/losa/tejado/cielo raso o una arista del boceto de escalera/rampa y haga clic en el lado deseado. La distancia está en la barra de opciones.',
  tl_tool_curtain_door: 'Puerta en muro cortina',
  tl_tool_curtain_window: 'Ventana en muro cortina',
  tl_hint_curtain_opening: '{label}: pase el cursor sobre el muro cortina; la celda bajo el cursor queda resaltada. Clic para insertar. Tab invierte el sentido, Espacio la bisagra. Esc cancela.',
