  tl_msg_curtain_confirm_fuse: 'La abertura {type} ({w} × {h} m) no cabe en la celda. ¿Fundir con las celdas vecinas?',
  tl_msg_curtain_fuse_refused: 'Nada cambió: la abertura no se insertó.',
  tl_hint_opening: '{label}: el lado del cursor define hacia dónde abre; pase el cursor sobre un muro y haga clic. Tab invierte el sentido, Espacio la bisagra.',
  tl_hint_parallel: 'Muro paralelo: haga clic en el muro base y luego en el lado deseado, o escriba la distancia y pulse Enter. Tab invierte el lado. La distancia se mide cara a cara (predeterminado) o entre ejes, según la barra de opciones. Escalera/rampa: use Editar boceto.',
  tl_hint_paste: 'Pegar: haga clic para colocar el contenido copiado. Esc cancela.',
  tl_hint_perimeter: 'Perímetro: elija una forma en la barra, o haga clic en una línea para seleccionarla. Finalizar cierra el contorno.',
  tl_hint_perim_select: 'Seleccione líneas: haga clic o arrastre una ventana (Shift suma, Ctrl resta, Ctrl+A todas). Suprimir elimina.',
  tl_hint_perim_slope: 'Pendiente: haga clic en el triángulo de una arista del contorno para activarla o desactivarla.',
