  tl_hint_perim_room: 'Por ambiente: haga clic dentro de un ambiente con circuito cerrado. Su contorno entra en el boceto.',
  tl_hint_ramp: 'Rampa: haga clic en el centro del borde de inicio. Esc cancela.',
  tl_hint_railing: 'Barandilla: haga clic en los puntos del recorrido. Intro termina, C cierra el recorrido. Esc cancela.',
  tl_undo_move_railing_vertex: 'Mover vértice de la barandilla',
