  tl_msg_railing_split: 'Barandilla dividida en dos.',
  tl_msg_railing_split_end: 'Haga clic en el interior del recorrido, lejos de los extremos.',
  tl_hint_ramp_free: 'Rampa libre: haga clic en el punto inicial. Esc cancela.',
  tl_hint_ramp_dir: 'Rampa: haga clic para dar la dirección y la longitud, o escriba el ángulo en grados (0 = eje X). Esc cancela el punto.',
  tl_hint_rehost: 'Cambiar anfitrión: haga clic en la abertura que desea mover (o selecciónela antes) y luego en el nuevo muro.',
  tl_hint_roof_arrow: 'Flecha de pendiente: haga clic en el alero del faldón y luego en el punto hacia donde sube. El faldón bajo el primer clic cambia; fuera de todo faldón, un nuevo faldón cubre el contorno.',
  tl_hint_roof_extrusion: 'Tejado por extrusión: haga clic en la primera esquina y luego en la esquina opuesta. El eje de la extrusión es el lado mayor (Tab cambia).',
  tl_hint_roof: 'Tejado: use Crear/Editar perímetro en la cinta de opciones.',
  tl_hint_room_sep: 'Línea de separación: haga clic en el punto inicial y luego en el punto final.',
  tl_hint_room: 'Ambiente: apunte a un circuito cerrado de muros y haga clic dentro de él.',
  tl_hint_move_section: 'Mover en sección: arrastre la selección. Horizontal mueve el muro/abertura; vertical cambia el antepecho de la ventana. Las anotaciones también se mueven.',
  tl_hint_align_section: 'Alinear en sección: haga clic en la referencia (parte superior, antepecho, jamba o centro) y luego en el destino. No hace falta seleccionar.',
  tl_hint_section: 'Sección: haga clic en el inicio de la línea de sección. Esc cancela.',
  tl_hint_select: 'Haga clic para seleccionar. Arrastre para una ventana (izq→der contiene, der→izq cruza). Shift o Ctrl suma a la selección.',
  tl_hint_slab_slope: 'Pendiente: seleccione una losa. Haga clic en el origen de la pendiente y luego en la dirección. Enter aplica el porcentaje de la barra.',
  tl_hint_slab: 'Losa: cree el contorno con el modo Crear/Editar perímetro.',
  tl_hint_split: 'Dividir: haga clic en el muro (punto de corte) o en una arista (inserta un vértice), incluido el boceto de escalera/rampa. Piso o losa: dos clics dividen. Escriba la distancia y pulse Enter para una medida exacta. Tab: con intervalo.',
  tl_hint_stair_run: 'Escalera: haga clic en el centro de la 1.ª contrahuella. Esc cancela.',
  tl_hint_stair_free: 'Escalera libre: haga clic en el punto inicial (centro de la 1.ª contrahuella). Esc cancela.',
  tl_hint_stair_dir: 'Escalera: haga clic para dar la dirección de subida, o escriba el ángulo en grados (0 = eje X). Esc cancela el punto.',
  tl_hint_spiral_start: 'Caracol: haga clic en el centro. Esc cancela.',
