  tl_hint_edge_copy: 'Copiar: seleccione elementos (Seleccionar) para copiar. Una arista sola aún no se puede copiar (ni de piso/losa, ni del boceto de escalera/rampa).',
  tl_hint_edge_move: 'Mover: seleccione elementos (Seleccionar) o haga clic en una arista de piso, losa, tejado, cielo raso o del boceto de escalera/rampa.',
