  tl_hint_ramp_dir: 'Rampe: Klicken Sie für Richtung und Länge, oder geben Sie den Winkel in Grad ein (0 = X-Achse). Esc verwirft den Punkt.',
  tl_hint_rehost: 'Bezug ändern: Klicken Sie die zu verschiebende Öffnung (oder wählen Sie sie vorher) und dann die neue Wand.',
  tl_hint_roof_arrow: 'Neigungspfeil: Klicken Sie den Dachüberstand der Dachfläche und dann den Punkt, zu dem sie ansteigt. Die Dachfläche unter dem ersten Klick ändert sich; außerhalb aller Dachflächen deckt eine neue Dachfläche die Kontur ab.',
  tl_hint_roof_extrusion: 'Dach durch Extrusion: Klicken Sie die erste Ecke und dann die gegenüberliegende. Die Extrusionsachse ist die längere Seite (Tab wechselt).',
