  tl_hint_room_sep: 'Trennlinie: Klicken Sie den Startpunkt und dann den Endpunkt.',
  tl_hint_room: 'Raum: Zeigen Sie auf einen geschlossenen Wandzug und klicken Sie hinein.',
  tl_hint_move_section: 'In Schnitt verschieben: Ziehen Sie die Auswahl. Horizontal bewegt Wand/Öffnung; vertikal ändert die Fensterbrüstung. Beschriftungen werden ebenfalls verschoben.',
  tl_hint_align_section: 'Im Schnitt ausrichten: Klicken Sie die Referenz (Oberkante, Brüstung, Gewände oder Mitte) und dann das Ziel. Keine Auswahl nötig.',
  tl_hint_section: 'Schnitt: Klicken Sie den Anfang der Schnittlinie. Esc bricht ab.',
  tl_hint_select: 'Klicken zum Auswählen. Ziehen für ein Fenster (links→rechts einschließend, rechts→links kreuzend). Shift oder Ctrl addiert zur Auswahl.',
  tl_hint_slab_slope: 'Neigung: Wählen Sie eine Decke. Klicken Sie den Ursprung des Gefälles und dann die Richtung. Enter wendet den Prozentsatz der Leiste an.',
  tl_hint_slab: 'Decke: Erstellen Sie die Kontur im Modus Umfang erstellen/bearbeiten.',
  tl_hint_split: 'Teilen: Klicken Sie die Wand (Schnittpunkt) oder eine Kante (fügt einen Scheitelpunkt ein), auch in der Treppen-/Rampenskizze. Boden oder Decke: zwei Klicks teilen. Geben Sie den Abstand ein und drücken Sie Enter für ein exaktes Maß. Tab: mit Lücke.',
  tl_hint_stair_run: 'Treppe: Klicken Sie die Mitte der 1. Setzstufe. Esc bricht ab.',
  tl_hint_stair_free: 'Freie Treppe: Klicken Sie den Startpunkt (Mitte der 1. Setzstufe). Esc bricht ab.',
  tl_hint_stair_dir: 'Treppe: Klicken Sie für die Steigrichtung, oder geben Sie den Winkel in Grad ein (0 = X-Achse). Esc verwirft den Punkt.',
  tl_hint_spiral_start: 'Wendel: Klicken Sie die Mitte. Esc bricht ab.',
  tl_hint_spiral_radius: 'Wendel: Klicken Sie den Außenradius und den Startwinkel (oder geben Sie den Radius in Metern ein). Rücktaste kehrt zur Mitte zurück.',
  tl_hint_stair_sketch: 'Treppe: Zeichnen Sie die linke Begrenzung; Enter wechselt zur rechten und ein weiteres Enter zu Setzstufen. Esc bricht die Kette ab; ein weiteres Esc verwirft die Skizze.',
  tl_hint_tag: 'Wählen Sie ein Element, starten Sie Beschriftung und klicken Sie auf die Position der Beschriftung.',
  tl_hint_text: 'Text: Klicken Sie die Position des Textes, geben Sie den Text ein und drücken Sie Enter.',
  tl_hint_move: '{label}: Klicken Sie den Basispunkt und dann das Ziel, oder geben Sie den Abstand ein.',
  tl_hint_edge_copy: 'Kopieren: Wählen Sie Elemente (Auswählen) zum Kopieren. Eine einzelne Kante kann noch nicht kopiert werden (weder von Boden/Decke noch aus der Treppen-/Rampenskizze).',
  tl_hint_edge_move: 'Verschieben: Wählen Sie Elemente (Auswählen) oder klicken Sie eine Kante von Boden, Decke, Dach, Unterdecke oder der Treppen-/Rampenskizze.',
  tl_hint_rotate: 'Drehen: Klicken Sie die Mitte, dann die Referenzrichtung und die Endrichtung — oder geben Sie den Winkel in Grad ein.',
  tl_hint_mirror: 'Spiegeln: Klicken Sie zwei Punkte für die Symmetrieachse. Tab: eine Wand als Achse wählen.',
  tl_hint_measure: 'Messen: Klicken Sie zwei Punkte. Das Maß bleibt in der Zeichnung bis Esc oder einen neuen Klick.',
  tl_hint_trim: 'Kürzen/Verlängern: Klicken Sie die Referenzwand und dann die zu verlängernde Wand auf der Seite, die bleiben soll. Kanten von Boden/Decke/Dach/Unterdecke oder der Treppen-/Rampenskizze: zwei Kanten, wie bei der Ecke.',
  tl_hint_wall: 'Wand: Klicken Sie den Startpunkt. Tab wechselt die Ausrichtungsreferenzen; Leertaste kehrt die Seite um.',

