/** Dicionário do idioma, com fallback EN→PT aplicado em 	. */
function dictFor(lang: Lang): Record<DictKey, string> {
  switch (lang) {
    case 'en': return EN;
    case 'es': return ES;
    case 'de': return DE;
    case 'fr': return FR;
    case 'it': return IT;
    case 'pl': return PL;
    default: return PT;
  }
}

